#!/usr/bin/env python3
"""Deterministically materialize the locally tested M4C3L 0017 intent bytes.

The ordinary patches/hf2/0017 runtime patch is NOT published by this carrier.
This script decodes the exact locally tested unified diff, verifies its SHA256,
writes it to a caller-selected path, and may apply it only to an exact post0016
working tree.  The human-readable design is in the M4C3L continuation.
"""
from __future__ import annotations
import argparse, base64, hashlib, subprocess, zlib
from pathlib import Path

EXPECTED_SHA256="8aa84fe086d090fabb84b7289aa9c8d7080eeabe5cd3a446b73f3c330b0bd40a"
PATCH_ZLIB_B64=""""""

def patch_bytes() -> bytes:
    data=zlib.decompress(base64.b64decode("".join(PATCH_ZLIB_B64.split())))
    got=hashlib.sha256(data).hexdigest()
    if got!=EXPECTED_SHA256:
        raise SystemExit(f"M4C3L intent digest mismatch: {got} != {EXPECTED_SHA256}")
    return data

def main() -> None:
    ap=argparse.ArgumentParser()
    ap.add_argument("--tree",required=True)
    ap.add_argument("--output",required=True)
    ap.add_argument("--apply",action="store_true")
    args=ap.parse_args()
    tree=Path(args.tree).resolve();out=Path(args.output).resolve()
    data=patch_bytes();out.parent.mkdir(parents=True,exist_ok=True);out.write_bytes(data)
    subprocess.run(["git","apply","--check",str(out)],cwd=tree,check=True)
    if args.apply:
        subprocess.run(["git","apply",str(out)],cwd=tree,check=True)
        subprocess.run(["git","diff","--check"],cwd=tree,check=True)
    print(f"patch_sha256={EXPECTED_SHA256}")
    print(f"patch_bytes={len(data)}")
    print(f"applied={str(bool(args.apply)).lower()}")

if __name__=="__main__":
    main()
